const tabId = 787783793;

// Let's search for Rush shoulder doctors directly on Google
const searchTerms = [
  "site:rushortho.com Nikhil Verma",
  "site:rushortho.com Grant Garrigues",
  "site:rushortho.com Gregory Nicholson",
  "site:nm.org Guido Marra",
  "site:nm.org Matthew Saltzman",
  "site:nm.org Michael Terry",
  "site:uchicagomedicine.org Lewis Shi",
  "site:uchicagomedicine.org Aravind Athiviraham",
  "site:ibji.com Roger Chams",
  "site:dulyhealthandcare.com Anthony Romeo"
];

const results = {};

for (const term of searchTerms) {
  await tool.navigate({ tabId, url: `https://www.google.com/search?q=${encodeURIComponent(term)}` });
  await tool.wait_for({ tabId, condition: "load_state", value: "load" });

  const link = await browserjs(tabId, () => {
    // Find the first external link or goto link
    const headings = Array.from(document.querySelectorAll('h3'));
    for (const h of headings) {
      const a = h.closest('a') || h.querySelector('a') || h.parentElement.querySelector('a');
      if (a && a.href) {
        return { title: h.innerText.trim(), href: a.href };
      }
    }
    return null;
  });
  results[term] = link;
}

console.log("Search results:", JSON.stringify(results, null, 2));

